#!/usr/bin/env python3
"""FS3 v179 - Silvio's notes on v178: the Sathanas in M77, one look for all
controls, strafing runs.

    M77       The Sathanas comes out of the middle of the portal and opens
              fire once a third of her is through; her main beams hold on
              three times as long (as the Lucifer's); she stays over the
              Hatshepsut until her beams have destroyed her - no script -
              and then drives on into the gas.
    UI        One rule for every button, tab and row: unavailable = the dark
              plate and dim text, the pointer on it = half ring, active = full
              ring. The bar buttons, the menus, locked rows and the log
              follow it.
    Flight    Against a large hull fighters and bombers fly strafing runs:
              in at a point on the hull, guns firing in a stream, through and
              well past, a wide turn and the next run - instead of circling
              and firing once per turn.

Needs v178. Edits src/10_core.js to src/70_ui.js in place, and writes the
updated fieldsim.js, hudsim.js and shipsim.js. Run assemble.py afterwards.
"""
import base64
import os
import sys

if "function noseOnHull" not in open("src/50_combat.js", encoding="utf-8").read():
    sys.exit("Abbruch: erst v178 einspielen.")
if "function btnState" in open("src/10_core.js", encoding="utf-8").read():
    sys.exit("Abbruch: v179 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)

